// Parsear artículos recibidos del subworkflow de procesamiento de sitio
const articlesStr = $input.item.json.articles;
const articles = typeof articlesStr === 'string' ? JSON.parse(articlesStr) : articlesStr;
const siteDomain = $input.item.json.siteDomain || 'unknown';

const startTime = Date.now();

// Devolver array de artículos para procesar
return articles.map((article, index) => ({
  json: {
    article_index: index,
    total_articles: articles.length,
    site_domain: siteDomain,
    current_article: article,
    start_time: startTime
  }
}));

// Procesar respuesta de AI con manejo de errores
const response = $input.item.json;
const articleData = $input.first().json;
const article = articleData.current_article;

let insight = '';
let aiSuccess = true;
let aiError = false;
let errorMessage = '';

// Verificar si hubo error en la llamada AI
if (response.error || !response.content) {
  aiSuccess = false;
  aiError = true;
  errorMessage = response.error?.message || 'AI API no retornó respuesta válida';

  // Fallback: insight genérico basado en el título
  const domain = articleData.site_domain;
  insight = `Contenido relevante sobre infraestructura y logística en ${domain}. Consulte el artículo completo para detalles específicos.`;
} else {
  // Parsear respuesta exitosa de Anthropic
  try {
    if (response.content && Array.isArray(response.content) && response.content.length > 0) {
      insight = response.content[0].text || '';
      insight = insight.trim().substring(0, 250);

      // Asegurar que termine apropiadamente si fue cortado
      if (insight.length === 250 && !insight.endsWith('.')) {
        insight = insight.substring(0, 247) + '...';
      }
    } else {
      throw new Error('Formato de respuesta inesperado');
    }
  } catch (e) {
    aiSuccess = false;
    aiError = true;
    errorMessage = e.message;
    insight = `Análisis de ${article.title.substring(0, 100)}. Ver artículo completo para más información.`;
  }
}

// Validar calidad del insight
const hasNumbers = /\d+/.test(insight);
const hasPercentage = /%/.test(insight);
const hasCurrency = /\$|USD|EUR|MXN/.test(insight);
const notGeneric = !/artículo|contenido|habla sobre|menciona que/i.test(insight);

let qualityScore = 0;
if (hasNumbers) qualityScore += 25;
if (hasPercentage) qualityScore += 25;
if (hasCurrency) qualityScore += 25;
if (notGeneric) qualityScore += 25;

return {
  json: {
    ...articleData,
    processed_article: {
      title: article.title,
      url: article.url,
      date: article.date,
      insight: insight,
      quality_score: qualityScore
    },
    ai_success: aiSuccess,
    ai_error: aiError,
    ai_error_message: errorMessage
  }
};

// Acumular todos los artículos procesados
const allItems = $input.all();
const processedArticles = allItems.map(item => item.json.processed_article);

// Estadísticas de procesamiento AI
const totalArticles = processedArticles.length;
const aiErrors = allItems.filter(item => item.json.ai_error).length;
const avgQualityScore = processedArticles.reduce((sum, a) => sum + (a.quality_score || 0), 0) / totalArticles;

const startTime = allItems[0].json.start_time;
const executionTime = Date.now() - startTime;

return {
  json: {
    processed_articles: processedArticles,
    insights_count: totalArticles,
    ai_errors_count: aiErrors,
    avg_quality_score: Math.round(avgQualityScore),
    execution_time_ms: executionTime,
    status: 'SUCCESS'
  }
};
